<script setup lang="ts">
type Situation = 'normal' | 'deliberate' | 'intrusive' | 'compartmentalised' | 'integrating'
type ExperienceProfile = 'ordinary' | 'voices' | 'compelling' | 'disrupted'
type Impulse = 'external' | 'internal' | 'bodily' | 'automatic'
const props = withDefaults(defineProps<{ locale?: 'nl' | 'en' }>(), { locale: 'nl' })
const nl = computed(() => props.locale === 'nl')
const permeability = ref(100), sourceRecognition = ref(100), attentionControl = ref(100), executionAccess = ref(100), deliberationTime = ref(100)
const activeSituation = ref<Situation | 'custom'>('normal'), selectedThought = ref(0)
const selectedProfile = ref<ExperienceProfile | 'custom'>('custom')
const networkView = ref<'process' | 'structure'>('process')
const selectedImpulse = ref<Impulse>('external'), animationStep = ref(0), playing = ref(false)
let animationTimer: ReturnType<typeof setInterval> | undefined
const situations: Record<Situation, [number, number, number, number, number]> = { normal:[100,100,100,100,100], deliberate:[86,91,82,92,90], intrusive:[72,48,19,58,62], compartmentalised:[34,38,24,42,74], integrating:[68,57,56,72,84] }
const situationLabels = computed<Record<Situation,string>>(() => ({
  normal:nl.value?'Normale integratie':'Ordinary integration', deliberate:nl.value?'Bewuste innerlijke spraak':'Deliberate inner speech', intrusive:nl.value?'Opdringende gedachte':'Intrusive thought', compartmentalised:nl.value?'Sterke informatiegrenzen':'Strong information boundaries', integrating:nl.value?'Groeiende doorlaatbaarheid':'Increasing permeability'
}))
const situationDescriptions = computed<Record<Situation,string>>(() => ({
 normal:nl.value?'Alle vier functies beginnen intact.':'All four functions start intact.', deliberate:nl.value?'Vrijwillig opgeroepen inhoud met herkenbare herkomst.':'Deliberately evoked content with a recognised origin.', intrusive:nl.value?'Inhoud dringt zich op terwijl bronherkenning en uitvoeringsinvloed afnemen.':'Content intrudes while source recognition and influence on execution decline.', compartmentalised:nl.value?'Relevante informatie is beperkt overdraagbaar tussen toestanden.':'Relevant information transfers only weakly between states.', integrating:nl.value?'Een overgangssituatie waarin verbindingen weer sterker worden.':'A transitional state in which connections become stronger again.'
}))
const experienceProfiles: Record<ExperienceProfile,[number,number,number,number,number]> = { ordinary:[100,100,100,100,100], voices:[68,35,62,88,78], compelling:[48,24,18,64,28], disrupted:[30,28,22,38,36] }
const profileLabels=computed<Record<ExperienceProfile,string>>(()=>({ordinary:nl.value?'Alledaagse toestand':'Everyday state',voices:nl.value?'Stemmen horen':'Hearing voices',compelling:nl.value?'Dwingende stemmen':'Compelling voices',disrupted:nl.value?'Ernstige ontregeling':'Severe disruption'}))
const profileDescriptions=computed<Record<ExperienceProfile,string>>(()=>({ordinary:nl.value?'Referentieprofiel zonder veronderstelde functieverstoring.':'Reference profile without assumed functional disruption.',voices:nl.value?'Illustratief profiel met vooral verminderde bronherkenning.':'Illustrative profile with mainly reduced source recognition.',compelling:nl.value?'Illustratief profiel met sterke aandachts- en handelingsdruk.':'Illustrative profile with strong pressure on attention and action.',disrupted:nl.value?'Eén hypothetisch profiel met brede verstoring; dit vertegenwoordigt geen psychiatrische diagnose.':'One hypothetical profile with broad disruption; it does not represent a psychiatric diagnosis.'}))
function applySituation(name: Situation) { activeSituation.value=name; selectedProfile.value='custom'; [permeability.value,sourceRecognition.value,attentionControl.value,executionAccess.value,deliberationTime.value]=situations[name] }
function applyProfile(name: ExperienceProfile | 'custom') { selectedProfile.value=name; if(name==='custom') return; activeSituation.value='custom'; [permeability.value,sourceRecognition.value,attentionControl.value,executionAccess.value,deliberationTime.value]=experienceProfiles[name] }
watch([permeability,sourceRecognition,attentionControl,executionAccess,deliberationTime],()=>{ const values=[permeability.value,sourceRecognition.value,attentionControl.value,executionAccess.value,deliberationTime.value]; if(activeSituation.value!=='custom'&&situations[activeSituation.value].some((v,i)=>v!==values[i])) activeSituation.value='custom'; if(selectedProfile.value!=='custom'&&experienceProfiles[selectedProfile.value].some((v,i)=>v!==values[i])) selectedProfile.value='custom' })
const ownership=computed(()=>Math.round(.64*sourceRecognition.value+.25*permeability.value+.11*attentionControl.value))
const arbitrationReach=computed(()=>Math.round(.47*permeability.value+.41*attentionControl.value+.12*sourceRecognition.value))
const control=computed(()=>Math.round(arbitrationReach.value*executionAccess.value/100))
const coherence=computed(()=>Math.round(.72*permeability.value+.18*sourceRecognition.value+.1*attentionControl.value))
const externalAttribution=computed(()=>Math.round(.7*(100-sourceRecognition.value)+.18*(100-permeability.value)+.12*(100-attentionControl.value)))
const thoughtProfiles=computed(()=>[
 {kind:nl.value?'Zelfkritische beoordeling':'Self-critical evaluation',origin:nl.value?'aangeleerde evaluatie en herinnering':'learned evaluation and memory',salience:72,urgency:38,action:22,automatic:48,description:nl.value?'Beoordeelt het zelf, trekt door emotionele betekenis aandacht, maar vraagt niet rechtstreeks om een handeling.':'Evaluates the self and attracts attention through emotional meaning, but does not directly request an action.'},
 {kind:nl.value?'Beschermend handelingscommando':'Protective action command',origin:nl.value?'snelle dreigings- of beschermingsrespons':'rapid threat or protective response',salience:94,urgency:92,action:96,automatic:84,description:nl.value?'Vraagt om onmiddellijke verplaatsing. Een automatische beschermingsreactie kan al beginnen voordat bewuste arbitrage is afgerond.':'Calls for immediate movement. An automatic protective response may begin before conscious arbitration is complete.'},
 {kind:nl.value?'Toekomstgerichte herinnering':'Prospective reminder',origin:nl.value?'prospectief geheugen':'prospective memory',salience:36,urgency:24,action:58,automatic:18,description:nl.value?'Vraagt om een latere handeling. Arbitrage kan de intentie bewaren zonder nu iets uit te voeren.':'Calls for later action. Arbitration may preserve the intention without executing anything now.'}
])
const thoughtProfile=computed(()=>thoughtProfiles.value[selectedThought.value])
const intrusion=computed(()=>Math.min(100,Math.round(thoughtProfile.value.salience*.55+(100-attentionControl.value)*.65)))
const executionOutcome=computed(()=>{
 const p=thoughtProfile.value
 if(p.action<30) return nl.value?'Geen directe handeling voorgesteld; de uitkomst is vooral een verandering in zelfbeoordeling of aandacht.':'No immediate action is proposed; the result mainly changes self-evaluation or attention.'
 if(p.automatic>70 && attentionControl.value<45 && executionAccess.value<65) return nl.value?'De automatische reactie kan al zijn ingezet; arbitrage kan haar slechts beperkt bijsturen of remmen.':'The automatic response may already be underway; arbitration can only partly redirect or inhibit it.'
 if(executionAccess.value<45) return nl.value?'Arbitrage bereikt een uitkomst, maar die krijgt onvoldoende toegang tot handelen of remming.':'Arbitration reaches an outcome, but it has insufficient access to action or inhibition.'
 if(selectedThought.value===2) return nl.value?'De gekozen uitkomst is uitstel: de intentie wordt bewaard voor een later geschikt moment.':'The selected outcome is delay: the intention is retained for a later suitable moment.'
 return nl.value?'De uitkomst van arbitrage kan uitvoering én het achterwege laten van uitvoering beïnvloeden.':'The outcome of arbitration can influence both execution and withholding execution.'
})
const route=computed(()=>{ const attributed=sourceRecognition.value>=62, shared=permeability.value>=58, wins=intrusion.value>=45; return [
  `${nl.value?'Een representatie ontstaat uit':'A representation arises from'} ${thoughtProfile.value.origin}`,
  shared?(nl.value?'Context en herkomst worden breed gedeeld':'Context and origin are widely shared'):(nl.value?'Context blijft deels afgeschermd':'Context remains partly separated'),
  attributed?(nl.value?'Herkomst wordt als zelfgegenereerd herkend':'Origin is recognised as self-generated'):(nl.value?'Herkomst blijft onzeker':'Origin remains uncertain'),
  wins?(nl.value?'De inhoud dringt de aandacht binnen':'The content captures attention'):(nl.value?'De inhoud blijft op de achtergrond':'The content remains in the background'),
  attributed?(nl.value?'Ervaring: “een gedachte van mij”':'Experience: “a thought of mine”'):(externalAttribution.value>62?(nl.value?'Mogelijke ervaring: “een andere stem”':'Possible experience: “another voice”'):(nl.value?'Mogelijke ervaring: “niet helemaal van mij”':'Possible experience: “not quite mine”')),
  executionOutcome.value ] })
const theories=computed(()=>[
  {name:nl.value?'Bronmonitoring':'Source monitoring',fit:Math.round(.72*(100-sourceRecognition.value)+.28*(100-attentionControl.value)),claim:nl.value?'De herkomst van zelfgegenereerde inhoud wordt onvoldoende herkend.':'The origin of self-generated content is insufficiently recognised.',test:nl.value?'Eigenaarschap moet vooral veranderen wanneer bronherkenning verbetert.':'Ownership should change especially when source recognition improves.'},
  {name:nl.value?'Informatiegrenzen':'Information boundaries',fit:Math.round(.7*(100-permeability.value)+.3*(100-sourceRecognition.value)),claim:nl.value?'Context, herinneringen of doelen zijn niet voldoende onderling beschikbaar.':'Context, memories or goals are insufficiently available to one another.',test:nl.value?'Herstel moet samengaan met meer overdracht tussen toestanden.':'Recovery should coincide with increased transfer between states.'},
  {name:nl.value?'Aandachtsregie':'Attentional control',fit:Math.round(.78*(100-attentionControl.value)+.22*(100-control.value)),claim:nl.value?'Interne inhoud krijgt onvrijwillig veel prioriteit en blijft actief.':'Internal content involuntarily receives high priority and remains active.',test:nl.value?'Lijdensdruk en opdringing moeten afnemen als aandachtsregie verbetert.':'Distress and intrusiveness should decline when attentional control improves.'},
  {name:nl.value?'Uitvoeringskoppeling':'Execution coupling',fit:Math.round(.75*(100-executionAccess.value)+.25*(100-arbitrationReach.value)),claim:nl.value?'Een bewuste uitkomst krijgt niet vanzelf toegang tot handelen of tot het remmen van een reactie.':'A conscious outcome does not automatically gain access to action or to inhibiting a response.',test:nl.value?'Begrip of keuze kan verbeteren zonder evenredige verandering in feitelijk gedrag.':'Understanding or choice may improve without a proportional change in actual behaviour.'},
  {name:nl.value?'Tijdsdruk':'Time pressure',fit:Math.round(.72*(100-deliberationTime.value)+.28*fastInfluence.value),claim:nl.value?'Arbitrage verzamelt niet voldoende informatie of bereikt de uitvoering te laat.':'Arbitration gathers insufficient information or reaches execution too late.',test:nl.value?'Dezelfde processen moeten meer invloed krijgen wanneer uitsluitend de beschikbare tijd toeneemt.':'The same processes should gain influence when only the available time increases.'},
  {name:nl.value?'Gecombineerd model':'Combined model',fit:Math.round(((100-permeability.value)+(100-sourceRecognition.value)+(100-attentionControl.value)+(100-executionAccess.value)+(100-deliberationTime.value))/5),claim:nl.value?'Meerdere processen versterken elkaar; geen enkele factor volstaat alleen.':'Several processes reinforce one another; no factor is sufficient alone.',test:nl.value?'Gerichte verandering van één factor moet andere uitkomsten slechts gedeeltelijk verbeteren.':'Changing one factor selectively should improve other outcomes only partly.'}
])
const thoughts=computed(()=>nl.value?['“Je kunt dit niet.”','“Ga bij de deur vandaan.”','“Ik moet straks nog bellen.”']:['“You cannot do this.”','“Move away from the door.”','“I still need to call later.”'])
const impulses=computed<Record<Impulse,{label:string,source:string}>>(()=>({
 external:{label:nl.value?'Externe waarneming':'External perception',source:nl.value?'geluid, beeld of aanraking':'sound, image or touch'},
 internal:{label:nl.value?'Andere gedachte':'Another thought',source:thoughts.value[selectedThought.value]},
 bodily:{label:nl.value?'Lichamelijk signaal':'Bodily signal',source:nl.value?'spanning, pijn of hartslag':'tension, pain or heartbeat'},
 automatic:{label:nl.value?'Snelle beschermingsimpuls':'Rapid protective impulse',source:nl.value?'dreigingsdetectie':'threat detection'}
}))
const impulseSalience=computed(()=>selectedImpulse.value==='internal'?thoughtProfile.value.salience:selectedImpulse.value==='automatic'?96:selectedImpulse.value==='bodily'?78:58)
const impulseActionDemand=computed(()=>selectedImpulse.value==='internal'?thoughtProfile.value.action:selectedImpulse.value==='automatic'?96:selectedImpulse.value==='bodily'?76:58)
const impulseAutomaticity=computed(()=>selectedImpulse.value==='internal'?thoughtProfile.value.automatic:selectedImpulse.value==='automatic'?96:selectedImpulse.value==='bodily'?64:34)
const clamp=(value:number)=>Math.max(0,Math.min(100,Math.round(value)))
const fastInfluence=computed(()=>clamp(.3*(100-attentionControl.value)+.24*(100-deliberationTime.value)+.2*impulseSalience.value+.16*impulseActionDemand.value+.1*impulseAutomaticity.value-23))
const consciousAccess=computed(()=>clamp(25+.55*impulseSalience.value+.2*permeability.value))
const arbitrationPotential=computed(()=>clamp(consciousAccess.value*arbitrationReach.value/100*(1-.55*fastInfluence.value/100)))
const arbitrationInfluence=computed(()=>clamp(arbitrationPotential.value*deliberationTime.value/100))
const arbitrationNow=computed(()=>clamp(arbitrationInfluence.value*Math.max(0,Math.min(1,(animationStep.value-1)/2))))
const executionInfluence=computed(()=>clamp(Math.max(fastInfluence.value,arbitrationInfluence.value*executionAccess.value/100)))
const processStages=computed(()=>[
 {x:65,y:282,label:nl.value?'impuls':'impulse'}, {x:155,y:205,label:nl.value?'lokale verwerking':'local processing'},
 {x:270,y:145,label:nl.value?'bewuste toegang':'conscious access'}, {x:385,y:165,label:nl.value?'arbitrage':'arbitration'},
 {x:475,y:230,label:nl.value?'uitvoering':'execution'}, {x:550,y:305,label:nl.value?'uitkomst':'outcome'}
])
const deliberativePath=computed(()=>{const s=processStages.value;return `M${s[0].x} ${s[0].y} Q105 235 ${s[1].x} ${s[1].y} Q210 155 ${s[2].x} ${s[2].y} Q330 135 ${s[3].x} ${s[3].y} Q440 185 ${s[4].x} ${s[4].y} Q535 265 ${s[5].x} ${s[5].y}`})
const fastPath=computed(()=>{const s=processStages.value;return `M${s[0].x} ${s[0].y} Q105 250 ${s[1].x} ${s[1].y} C255 290 380 315 ${s[4].x} ${s[4].y} Q535 265 ${s[5].x} ${s[5].y}`})
const deliberativePoint=computed(()=>processStages.value[Math.min(animationStep.value,5)])
const fastPoints=computed(()=>[processStages.value[0],processStages.value[1],processStages.value[4],processStages.value[5],processStages.value[5],processStages.value[5]])
const fastPoint=computed(()=>fastPoints.value[Math.min(animationStep.value,5)])
const processStrengths=computed(()=>[100,100,consciousAccess.value,arbitrationNow.value,executionInfluence.value,executionInfluence.value])
const processOutcome=computed(()=>{
 if(executionAccess.value<45) return nl.value?'besluit niet uitgevoerd':'decision not executed'
 if(selectedThought.value===2 && selectedImpulse.value==='internal') return nl.value?'intentie bewaard':'intention retained'
 if(fastInfluence.value>arbitrationInfluence.value*1.5) return nl.value?'snelle invloed domineert':'rapid influence dominates'
 if(arbitrationInfluence.value>fastInfluence.value*1.5) return nl.value?'arbitrage domineert':'arbitration dominates'
 return nl.value?'gemengde invloed':'mixed influence'
})
function stopAnimation(){ if(animationTimer) clearInterval(animationTimer); animationTimer=undefined; playing.value=false }
function startAnimation(){ stopAnimation(); if(animationStep.value>=5) animationStep.value=0; playing.value=true; animationTimer=setInterval(()=>{ if(animationStep.value>=5) stopAnimation(); else animationStep.value++ },850) }
function restartAnimation(){ animationStep.value=0; startAnimation() }
watch([selectedImpulse,selectedThought,networkView],()=>{ animationStep.value=0; if(networkView.value==='process') startAnimation(); else stopAnimation() })
onMounted(()=>{ if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches) startAnimation() })
onUnmounted(stopAnimation)
const scoreTone=(score:number)=>score>67?'high':score>39?'middle':'low'
</script>

<template>
 <section class="self-explorer" data-analytics-model="self-organization">
  <header><p class="eyebrow">{{nl?'INTERACTIEVE HYPOTHESEVERGELIJKER':'INTERACTIVE HYPOTHESIS COMPARATOR'}}</p><h3>{{nl?'Wanneer voelt een gedachte als van mij?':'When does a thought feel like mine?'}}</h3><p>{{nl?'Verander vijf veronderstelde processen en vergelijk verschillende soorten gedachten. Het model scheidt bewuste toegang, groeiende arbitrage en de mogelijkheid om haar uitkomst nog op tijd uit te voeren.':'Change five proposed processes and compare different kinds of thought. The model separates conscious access, accumulating arbitration and the ability to execute its outcome in time.'}}</p></header>
  <p class="control-label">{{nl?'Mechanistische voorbeelden':'Mechanistic examples'}}</p><div class="presets" role="group" :aria-label="nl?'Mechanistische voorbeelden':'Mechanistic examples'"><button v-for="(_,name) in situations" :key="name" type="button" :class="{active:activeSituation===name}" @click="applySituation(name as Situation)">{{situationLabels[name as Situation]}}</button></div><p v-if="activeSituation!=='custom'" class="preset-note">{{situationDescriptions[activeSituation as Situation]}}</p>
  <div class="profile-picker"><label><span>{{nl?'Begin vanuit een ervaringsprofiel':'Start from an experience profile'}}</span><select :value="selectedProfile" @change="applyProfile(($event.target as HTMLSelectElement).value as ExperienceProfile | 'custom')"><option value="custom">{{nl?'Handmatige configuratie':'Manual configuration'}}</option><option v-for="(_,name) in experienceProfiles" :key="name" :value="name">{{profileLabels[name as ExperienceProfile]}}</option></select></label><p v-if="selectedProfile!=='custom'">{{profileDescriptions[selectedProfile as ExperienceProfile]}}</p></div>
  <div class="explorer-grid">
   <section class="controls panel"><h4>{{nl?'Veronderstelde processen':'Proposed processes'}}</h4>
    <label><span><b>{{nl?'Informatiedoorlaatbaarheid':'Information permeability'}}</b><output>{{permeability}}%</output></span><input v-model.number="permeability" type="range" min="0" max="100"><small>{{nl?'Kunnen relevante herinneringen, emoties en doelen tussen toestanden meewegen?':'Can relevant memories, emotions and goals transfer between states?'}}</small></label>
    <label><span><b>{{nl?'Bronherkenning':'Source recognition'}}</b><output>{{sourceRecognition}}%</output></span><input v-model.number="sourceRecognition" type="range" min="0" max="100"><small>{{nl?'Wordt interne inhoud als zelfgegenereerd herkend?':'Is internally generated content recognised as self-generated?'}}</small></label>
    <label><span><b>{{nl?'Aandachtsregie':'Attentional control'}}</b><output>{{attentionControl}}%</output></span><input v-model.number="attentionControl" type="range" min="0" max="100"><small>{{nl?'In hoeverre kan aandacht flexibel worden gericht en van opdringende inhoud worden losgemaakt?':'How flexibly can attention be directed and disengaged from intrusive content?'}}</small></label>
    <label><span><b>{{nl?'Toegang tot uitvoering':'Access to execution'}}</b><output>{{executionAccess}}%</output></span><input v-model.number="executionAccess" type="range" min="0" max="100"><small>{{nl?'Kan de uitkomst van arbitrage handelen starten, wijzigen of juist tegenhouden?':'Can the outcome of arbitration start, alter or inhibit action?'}}</small></label>
    <label><span><b>{{nl?'Tijd voor afweging':'Time for deliberation'}}</b><output>{{deliberationTime}}%</output></span><input v-model.number="deliberationTime" type="range" min="0" max="100"><small>{{nl?'Hoeveel tijd is beschikbaar om informatie te verzamelen voordat uitvoering moeilijk omkeerbaar wordt?':'How much time is available to gather information before execution becomes difficult to reverse?'}}</small></label>
   </section>
   <section class="network panel"><div class="panel-heading"><h4>{{networkView==='process'?(nl?'Van impuls naar uitkomst':'From impulse to outcome'):(nl?'Actuele zelforganisatie':'Current self-organisation')}}</h4><div class="view-switch"><button type="button" :class="{active:networkView==='process'}" @click="networkView='process'">{{nl?'Proces':'Process'}}</button><button type="button" :class="{active:networkView==='structure'}" @click="networkView='structure'">{{nl?'Structuur':'Structure'}}</button></div></div>
    <p class="model-purpose">{{networkView==='process'?(nl?'Dit procesmodel laat zien langs welke routes één impuls invloed kan krijgen op aandacht, arbitrage en uiteindelijk gedrag.':'This process model shows the routes through which one impulse can influence attention, arbitration and ultimately behaviour.'):(nl?'Dit structuurmodel toont welke functies op dit moment informatie met de arbitrage kunnen uitwisselen en hoeveel invloed zij hebben.':'This structure model shows which functions can currently exchange information with arbitration and how much influence they have.')}}</p>
    <div v-if="networkView==='process'" class="process-view">
     <div class="impulse-picker" role="group" :aria-label="nl?'Bron van de impuls':'Source of the impulse'"><button v-for="(impulse,key) in impulses" :key="key" type="button" :class="{active:selectedImpulse===key}" @click="selectedImpulse=key as Impulse"><span>{{impulse.label}}</span><small>{{impulse.source}}</small></button></div>
     <svg class="process-map" viewBox="0 0 640 370" role="img" :aria-label="nl?'Geanimeerde functionele boog van impuls via verwerking en arbitrage naar een uitkomst':'Animated functional arc from impulse through processing and arbitration to an outcome'">
      <path :d="deliberativePath" class="process-path" :style="{strokeOpacity:Math.max(.08,arbitrationNow/100)}"/><path :d="fastPath" class="process-path bypass" :style="{strokeOpacity:Math.max(.04,fastInfluence/100)}"/>
      <line x1="305" y1="275" x2="385" y2="165" class="context-line" :style="{strokeOpacity:permeability/100}"/><line x1="385" y1="65" x2="385" y2="165" class="context-line" :style="{strokeOpacity:impulseSalience/100}"/><line x1="475" y1="110" x2="385" y2="165" class="context-line" :style="{strokeOpacity:coherence/100}"/>
      <g v-for="(stage,index) in processStages" :key="stage.label" class="process-node"><circle :cx="stage.x" :cy="stage.y" r="29" :style="{fillOpacity:processStrengths[index]/100}"/><text :x="stage.x" :y="stage.y" text-anchor="middle">{{index+1}}</text><text :x="stage.x" :y="stage.y+16" text-anchor="middle" class="node-value">{{processStrengths[index]}}%</text><text :x="stage.x" :y="stage.y+45" text-anchor="middle" class="node-label">{{index===5?processOutcome:stage.label}}</text></g>
      <g class="context-node"><circle cx="305" cy="275" r="17" :style="{fillOpacity:permeability/100}"/><text x="305" y="305" text-anchor="middle">{{nl?'context':'context'}}</text><circle cx="385" cy="65" r="17" :style="{fillOpacity:impulseSalience/100}"/><text x="385" y="39" text-anchor="middle">{{nl?'emotie':'emotion'}}</text><circle cx="475" cy="110" r="17" :style="{fillOpacity:coherence/100}"/><text x="507" y="114" text-anchor="start">{{nl?'doelen':'goals'}}</text></g>
      <circle class="signal deliberative-signal" :cx="deliberativePoint.x" :cy="deliberativePoint.y" r="10" :style="{opacity:Math.max(.08,arbitrationNow/100)}"/><circle class="signal fast-signal" :cx="fastPoint.x" :cy="fastPoint.y" r="8" :style="{opacity:Math.max(.04,fastInfluence/100)}"/>
     </svg>
     <div class="animation-controls"><p><strong>{{impulses[selectedImpulse].label}}:</strong> {{impulses[selectedImpulse].source}} · <strong>{{nl?'verwachte uitkomst':'expected outcome'}}:</strong> {{processOutcome}}</p><button type="button" @click="playing?stopAnimation():startAnimation()">{{playing?(nl?'Pauze':'Pause'):(nl?'Verder':'Continue')}}</button><button type="button" @click="restartAnimation">{{nl?'Opnieuw':'Replay'}}</button></div>
     <p class="network-note"><strong>{{nl?'Gelijktijdige invloeden:':'Concurrent influences:'}}</strong> {{nl?`bewuste toegang ${consciousAccess}%, arbitrage nu ${arbitrationNow}% van maximaal ${arbitrationInfluence}%, en snelle invloed ${fastInfluence}%. Minder beschikbare tijd verlaagt het haalbare maximum en geeft de snelle invloed relatief meer voorsprong.`:`conscious access ${consciousAccess}%, arbitration now ${arbitrationNow}% of a maximum ${arbitrationInfluence}%, and rapid influence ${fastInfluence}%. Less available time lowers the attainable maximum and gives rapid influence a greater relative head start.`}} {{nl?'De beweging toont een functionele volgorde, geen letterlijke zenuwbaan of gemeten verwerkingstijd.':'The movement shows functional order, not a literal neural pathway or measured processing time.'}}</p>
    </div>
    <svg v-else viewBox="0 0 520 365" role="img" :aria-label="nl?'Netwerk met percentages voor informatie, emotie, doelen, zelftoeschrijving, arbitrage en uitvoering':'Network with percentages for information, emotion, goals, self-attribution, arbitration and execution'">
     <line x1="260" y1="156" x2="100" y2="75" :style="{strokeOpacity:permeability/100}"/><line x1="260" y1="156" x2="415" y2="78" :style="{strokeOpacity:thoughtProfile.salience/100}"/><line x1="260" y1="156" x2="116" y2="253" :style="{strokeOpacity:coherence/100}"/><line x1="260" y1="156" x2="404" y2="249" :style="{strokeOpacity:ownership/100}"/><line x1="260" y1="156" x2="260" y2="318" :style="{strokeOpacity:executionAccess/100}"/>
